---FreshTimes
--- 刷新猫的训练次数 或 猫的剩余培育次数
function CatHouseListBtnNode:FreshTimes(trainTimeLimit)
    local catData     = self.catData
    local age         = checkNumber(catData.age)
    local isAdult     = age == BornType.Adult
    local isBaby      = age == BornType.Baby
    local trainingTimes = checkNumber(catData.trainingTimes)
    local isShowTrainingTimes = isBaby and trainingTimes < trainTimeLimit
    KTool.SetActive(self.HatchTimes.gameObject, isAdult)
    KTool.SetActive(self.TrainTimes.gameObject, isShowTrainingTimes)
    KTool.SetActive(self.Upgradeable.gameObject, isBaby and trainingTimes >= trainTimeLimit)
    if isAdult then
        ---刷新剩余孵化次数
        self.HatchTimesTextNumber.text = catData.deliveryRemainTimes
    elseif isShowTrainingTimes then
        --- 刷新训练次数
        self.TrainTimesTextNumber.textComp.text = trainTimeLimit - trainingTimes
    end

end

