function CatHouseListBtnNode:FreshCountdownNode()
    ---@type CatHouseCountdownNode
    local env = CfUtils.GetLuaScr(self.CatHouseCountdownNode, CatHouseCountdownNodeEnvPath)
    if env == nil then return end
    env:FreshUI(self.catData)
end

---FreshAttrDetails
--- 刷新属性详情
function CatHouseListBtnNode:FreshAttrDetails()
    local parent         = self.AttributeDetails
    local AttributeNodeCache = self.AttributeNodeCache
    ---@type BaseSetting
    local setting      = CfUtils.GetCf(AutoIds.IdSetting1901, "CatHouseCatAttributeVo")
    ---@type CatHouseCatAttributeVo[]
    local attributeVos = setting:GetAll()

    local attr = self.catData.attr
    ---@param v CatHouseCatAttributeVo
    for i, v in ipairs(attributeVos) do
        -----------------------------
        --- 获取或初始化缓存结点
        local cache       = AttributeNodeCache[i]
        local attrNode, imgIcon, textNumber
        if cache then
            attrNode, imgIcon, textNumber = SafeUnpack(cache)
        else
            attrNode              = parent.gameObject:AddChild(self.AttributeNode.gameObject)  
            cache                 = {attrNode.gameObject}  
            AttributeNodeCache[i] = cache
        end
        if imgIcon == nil then
            local temp = attrNode.transform:Find("ImgIcon")
            imgIcon    = temp.gameObject:GetComponent(RawImageAlterableType)
            table.insert(cache, imgIcon)
        end
        if textNumber == nil then
            local temp = attrNode.transform:Find("TextNumber")
            textNumber = temp.gameObject:GetComponent(TextMeshProUGUIType)
            table.insert(cache, textNumber)
        end
        
        -----------------------------
        --- 刷新UI
        KTool.SetActive(attrNode.gameObject, true)
        local attributeId = v.id
        local attrNum     = attr[checkString(attributeId)]
        local pathIcon = checkString(v.picture)
        imgIcon:LoadSprite(pathIcon)
        textNumber.text = attrNum
    end

end

function CatHouseListBtnNode:FreshStatusDisplayShowState(isShow)
    KTool.SetActive(self.StatusDisplay.gameObject, isShow == 1)

end

function CatHouseListBtnNode:FreshRallyUI(goodsId)
    local catData = self.catData
    local price   = checkNumber(catData.price)
    KTool.SetActive(self.MarketPrice.gameObject, true)

    ---@type GoodsVo
    if self.goodsId == nil then
        self.goodsId = goodsId
        local goodsVo    = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        self.MarketPriceImgIcon:LoadSprite(goodsVo.photoPath)
    end

    local num = GoodsUtils.GetThingNo(goodsId)
    self.MarketPriceTextNumber.Status = num >= price and 1 or 2
    self.MarketPriceTextNumber.textComp.text = price
end

