function CatHouseListBtnNode:OnEventCaptureTextureCompleteAction(id, path)
    if self.fileNameId ~= id then return end
    if not self.loading then return end
    self.loading = false
    if self.AnimRootAnimComp then
        self.AnimRootAnimComp:Play(DefaultHash)
    end
    local texture = CatHouseMgr:GetInstance():LoadCaptureTexture(path, self.isMarket)
    local ImgIconCat = self.ImgIconCat
    --- 列表子节点重叠看bugly 挺像 ImgIconCat 类型错误
    if ImgIconCat:GetType() ~= RawImageType then
        ImgIconCat = ImgIconCat.gameObject:GetComponent(RawImageType)        
    end
    ImgIconCat.texture = texture
end

function CatHouseListBtnNode:OnClickNodeAction()
    if self.callback then
        self.callback(self.catData, self.controller.gameObject)
        Events.Broadcast(Constants.EventNames.CatHouseExploreCatCellClick, self.catData, self.controller)
    end
end

---------------------------------------------------
--- handler end --
